Author: Nikos Mavrogiannopoulos <nmav@redhat.com>
Date:   Fri Apr 28 22:46:48 2017 +0200

    pkcs12: release CRL data on error path

    This addresses issue:
      https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=1295

    Signed-off-by: Nikos Mavrogiannopoulos <nmav@redhat.com>
---
 lib/x509/pkcs12.c | 4 ++++
 1 file changed, 4 insertions(+)

diff --git a/lib/x509/pkcs12.c b/lib/x509/pkcs12.c
index e71d1f01d..16a015cb7 100644
--- a/lib/x509/pkcs12.c
+++ b/lib/x509/pkcs12.c
@@ -1690,200 +1690,204 @@ gnutls_pkcs12_simple_parse(gnutls_pkcs12_t p12,
                                                gnutls_realloc_fast
                                                (_extra_certs,
                                                 sizeof(_extra_certs
                                                        [0]) *
                                                 ++_extra_certs_len);
                                        if (!_extra_certs) {
                                                gnutls_assert();
                                                ret =
                                                        GNUTLS_E_MEMORY_ERROR;
                                                goto done;
                                        }
                                        _extra_certs
                                                [_extra_certs_len -
                                                 1] = this_cert;
                                        this_cert = NULL;
                                } else {
                                        if (chain && _chain_len == 0) {
                                                _chain =
                                                    gnutls_malloc(sizeof
                                                                  (_chain
                                                                   [0]) *
                                                                  (++_chain_len));
                                                if (!_chain) {
                                                        gnutls_assert();
                                                        ret =
                                                            GNUTLS_E_MEMORY_ERROR;
                                                        goto done;
                                                }
                                                _chain[_chain_len - 1] =
                                                    this_cert;
                                                this_cert = NULL;
                                        } else {
                                                gnutls_x509_crt_deinit
                                                    (this_cert);
                                        }
                                }
                                break;

                        case GNUTLS_BAG_CRL:
                                if (crl == NULL || *crl != NULL) {
                                        gnutls_assert();
                                        break;
                                }

                                ret = gnutls_x509_crl_init(crl);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                ret =
                                    gnutls_x509_crl_import(*crl, &data,
                                                           GNUTLS_X509_FMT_DER);
                                if (ret < 0) {
                                        gnutls_assert();
                                        gnutls_x509_crl_deinit(*crl);
                                        goto done;
                                }
                                break;

                        case GNUTLS_BAG_ENCRYPTED:
                                /* XXX Bother to recurse one level down?  Unlikely to
                                   use the same password anyway. */
                        case GNUTLS_BAG_EMPTY:
                        default:
                                break;
                        }
                }

                idx++;
                gnutls_pkcs12_bag_deinit(bag);
                bag = NULL;
        }

        if (chain != NULL) {
                if (_chain_len != 1) {
                        ret = GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
                        goto done;
                }

                ret =
                    make_chain(&_chain, &_chain_len, &_extra_certs,
                               &_extra_certs_len, flags);
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }
        }

        ret = 0;

       done:
        if (bag)
                gnutls_pkcs12_bag_deinit(bag);

        if (ret < 0) {
                if (*key) {
                        gnutls_x509_privkey_deinit(*key);
                        *key = NULL;
                }
+               if (crl != NULL && *crl != NULL) {
+                       gnutls_x509_crl_deinit(*crl);
+                       *crl = NULL;
+               }
                if (_extra_certs_len && _extra_certs != NULL) {
                        for (i = 0; i < _extra_certs_len; i++)
                                gnutls_x509_crt_deinit(_extra_certs[i]);
                        gnutls_free(_extra_certs);
                }
                if (_chain_len && _chain != NULL) {
                        for (i = 0; i < _chain_len; i++)
                                gnutls_x509_crt_deinit(_chain[i]);
                        gnutls_free(_chain);
                }

                return ret;
        }

        if (extra_certs && _extra_certs_len > 0) {
                *extra_certs = _extra_certs;
                *extra_certs_len = _extra_certs_len;
        } else {
                if (extra_certs) {
                        *extra_certs = NULL;
                        *extra_certs_len = 0;
                }
                for (i = 0; i < _extra_certs_len; i++)
                        gnutls_x509_crt_deinit(_extra_certs[i]);
                gnutls_free(_extra_certs);
        }

        if (chain != NULL) {
                *chain = _chain;
                *chain_len = _chain_len;
        }

        return ret;
 }


